<section class="editorial-hero" aria-labelledby="hero-title">
	<div class="hero-copy"><p class="eyebrow">Shopping, handled your way.</p><h1 id="hero-title">You list it.<br /><span>They get it.</span></h1><p class="summary">Create your shopping list, choose a verified procurer near your delivery location, and get your shopping handled.</p><div class="hero-actions"><a class="primary" href="/register">Start shopping <span aria-hidden="true">↗</span></a><a class="secondary" href="/how-it-works">See how it works</a></div><p class="control-note"><span aria-hidden="true">✓</span> The list and quote stay in your hands.</p></div>
	<div class="hero-art"><img src="/illustrations/marketing/customer-procurer-scene.svg" alt="A customer sends a shopping list along a connected path to a verified local procurer." fetchpriority="high" /><span class="caption">A good plan, made together.</span></div>
</section>

<style>
	.editorial-hero{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);align-items:center;gap:clamp(24px,5vw,76px);min-height:min(760px,calc(100svh - 72px));padding:clamp(48px,7vw,100px) clamp(24px,7vw,100px);color:var(--text-primary);background:var(--background-canvas)}.hero-copy{position:relative;z-index:1;max-width:560px;animation:hero-copy-enter 700ms var(--motion-easing-standard) both}.eyebrow{margin:0 0 19px;color:var(--action-primary);font-size:12px;font-weight:850;letter-spacing:.14em;text-transform:uppercase}.hero-copy h1{margin:0;font:800 clamp(58px,8.2vw,120px)/.9 'Space Grotesk',sans-serif;letter-spacing:-.075em}.hero-copy h1 span{color:var(--action-primary)}.summary{max-width:480px;margin:26px 0 24px;color:var(--text-secondary);font-size:clamp(16px,1.55vw,19px);line-height:1.6}.hero-actions{display:flex;align-items:center;gap:22px;flex-wrap:wrap;animation:hero-cta-enter 700ms 280ms var(--motion-easing-standard) both}.hero-actions a{display:inline-flex;min-height:54px;align-items:center;justify-content:center;gap:22px;padding:0 18px;border-radius:10px;font-size:14px;font-weight:750;text-decoration:none;transition:transform var(--motion-fast) var(--motion-easing-standard),background-color var(--motion-fast) var(--motion-easing-standard)}.hero-actions a:hover{transform:translateY(-2px)}.primary{color:var(--action-on-primary);background:var(--action-primary)}.secondary{color:var(--text-primary);border:1px solid var(--border-strong);background:var(--background-surface)}.control-note{display:flex;align-items:center;gap:10px;margin:24px 0 0;color:var(--text-secondary);font-size:13px}.control-note span{display:grid;width:23px;height:23px;place-items:center;border-radius:50%;color:#153d2e;background:var(--accent-lime);font-weight:800}.hero-art{position:relative;display:grid;min-height:490px;place-items:center;border-radius:40% 18px 18px 18px;background:var(--background-subtle);overflow:hidden;animation:hero-art-enter 900ms 160ms var(--motion-easing-standard) both}.hero-art img{width:min(100%,780px);height:auto;max-height:590px;object-fit:contain}.caption{position:absolute;right:24px;bottom:18px;color:var(--text-secondary);font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
	@media(max-width:850px){.editorial-hero{grid-template-columns:1fr;gap:28px;min-height:0;padding:40px 24px 48px}.hero-copy{max-width:650px}.hero-copy h1{font-size:clamp(64px,15vw,94px)}.summary{max-width:540px;margin:19px 0 18px}.hero-art{min-height:0;aspect-ratio:1.28;border-radius:32% 18px 18px 18px}.hero-art img{width:100%;height:100%;object-fit:contain}.caption{right:14px;bottom:12px;font-size:9px}}
	@media(max-width:420px){.editorial-hero{padding:34px 18px 40px}.hero-copy h1{font-size:clamp(60px,16vw,78px)}.hero-art{aspect-ratio:1.08}.hero-actions{gap:12px}.hero-actions a{min-height:50px}.control-note{align-items:flex-start;font-size:12px}}
	@keyframes hero-copy-enter{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}@keyframes hero-art-enter{from{opacity:0;transform:translateY(22px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes hero-cta-enter{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.hero-copy,.hero-art,.hero-actions{animation:none}}
</style>
